globalCss:
.scene {
  --cream: #F5F2EA;
  --cream-2: #EBE5D7;
  --rule: #D5CEBE;
  --ink: #12211A;
  --ink-2: #33443B;
  --muted: #5E6D65;
  --faint: #A0A9A3;
  --green: #1E8E63;
  --green-600: #197854;
  --green-700: #145F43;
  --green-100: #EAF4F0;
  --mint: #96CAB6;
  --yellow: #F5B700;
  --yellow-200: #FDEDC0;
  --yellow-700: #A57B00;
  --blue: #1D5FA8;
  --blue-100: #EAF0F7;
  --blue-200: #C7D7E9;
  --blue-300: #96B4D6;
  --blue-400: #5C8BC0;
  --red: #D6453D;
  --red-100: #FBEDED;
  --red-900: #441613;
  --night: #0F1A15;
  --night-2: #14231C;
  --night-rule: #2A3C33;
  --night-text: #E4EEE8;
  --night-muted: #8DA196;
  --sans: 'IBM Plex Sans', system-ui, sans-serif;
  --cond: 'IBM Plex Sans Condensed', 'IBM Plex Sans', sans-serif;
  --mono: 'IBM Plex Mono', ui-monospace, Consolas, monospace;

  position: relative;
  width: 1920px;
  height: 1080px;
  overflow: hidden;
  box-sizing: border-box;
  padding: 84px 128px 0;
  background: var(--cream);
  color: var(--ink);
  font: 400 27px/1.42 var(--sans);
  -webkit-font-smoothing: antialiased;
}
.scene *, .scene *::before, .scene *::after { box-sizing: border-box; }
.scene p, .scene h1, .scene h2, .scene h3, .scene h4, .scene ul, .scene ol, .scene figure, .scene dl, .scene dd, .scene pre { margin: 0; padding: 0; }
.scene ul, .scene ol { list-style: none; }
.scene b, .scene strong { font-weight: 600; }
.scene code, .scene .mono { font-family: var(--mono); }
.scene .num { font-variant-numeric: tabular-nums; }

.scene.tone-dark { background: var(--night); color: var(--night-text); }
.scene.tone-green { background: var(--green); color: #fff; }

/* --- header: the five parts of the pitch, then the title ---------------- */
/* The top right corner stays empty: the speaker tag lands there. */
.scene .parts { display: flex; gap: 40px; font: 500 18px/1 var(--sans); color: var(--faint); }
.scene .parts span { position: relative; padding-bottom: 12px; white-space: nowrap; }
.scene .parts b { font-family: var(--cond); font-weight: 600; margin-right: 8px; }
.scene .parts .on { color: var(--ink); }
.scene .parts .on::after { content: ""; position: absolute; left: 0; right: 0; bottom: 0; height: 3px; background: var(--green); }
.scene.tone-dark .parts { color: #56695E; }
.scene.tone-dark .parts .on { color: var(--night-text); }
.scene.tone-dark .parts .on::after { background: var(--mint); }
.scene .title { margin-top: 32px; max-width: 1180px; font: 600 64px/1.06 var(--sans); letter-spacing: -.012em; }

/* Content area: same top on every scene. */
.scene .body { position: absolute; left: 128px; right: 128px; top: 272px; bottom: 72px; }
.scene .grid12 { display: grid; grid-template-columns: repeat(12, 1fr); column-gap: 32px; }
.scene .label { font: 500 19px/1.2 var(--sans); color: var(--muted); }
.scene.tone-dark .label { color: var(--night-muted); }
.scene .note { position: absolute; left: 128px; right: 128px; bottom: 36px; font: 400 19px/1.3 var(--sans); color: var(--muted); }
.scene.tone-dark .note { color: var(--night-muted); }
/* Highlighter. The video sweeps it in (data-anim="highlight" drives --hl). */
.scene mark {
  color: inherit;
  padding: 0 .06em;
  background: linear-gradient(var(--yellow-200), var(--yellow-200)) no-repeat 0 100% / var(--hl, 100%) .38em;
}
.scene.tone-dark mark { background: none; color: color-mix(in srgb, var(--yellow) var(--hl, 100%), var(--night-text)); }
.scene.tone-green mark { background: none; color: color-mix(in srgb, var(--yellow) var(--hl, 100%), #fff); }
.scene .sq { display: inline-block; width: 14px; height: 14px; margin-right: 12px; vertical-align: 1px; }
.scene .sq.ia { background: var(--yellow-200); box-shadow: inset 0 0 0 2px var(--yellow-700); }
.scene .sq.ds { background: var(--blue); }
.scene .sq.ok { background: var(--green); }
.scene .sq.bad { background: var(--red); }

/* --- figures (camera) ---------------------------------------------------- */
.scene .fig-stage { position: absolute; left: 128px; right: 128px; top: 272px; bottom: 168px; border-radius: 6px; overflow: hidden; background: #fff; box-shadow: inset 0 0 0 1px var(--rule); }
.scene .fig-canvas { position: absolute; left: 0; top: 0; transform-origin: 0 0; }
.scene .focus { position: absolute; display: block; pointer-events: none; }
.scene .fig-caption { position: absolute; left: 128px; right: 128px; bottom: 48px; display: grid; grid-template-columns: repeat(12, 1fr); column-gap: 32px; font: 400 21px/1.35 var(--sans); }
.scene .fig-caption > p { grid-column: span 4; padding-top: 16px; border-top: 1px solid var(--rule); color: var(--ink-2); }
.scene .fig-caption b { display: block; margin-bottom: 4px; font-weight: 600; color: var(--ink); }

/* --- team ---------------------------------------------------------------- */
.scene .member { display: flex; align-items: center; gap: 16px; }
.scene .member img { width: 88px; height: 88px; border-radius: 50%; border: 3px solid var(--yellow); flex: none; }
.scene .member figcaption { font: 600 21px/1.25 var(--sans); }
.scene .member small { display: block; margin-top: 8px; font: 400 17px/1 var(--mono); color: #CFEBDD; }

/* --- 01 grupo ------------------------------------------------------------ */
.s-cover .brand, .s-fim .brand { display: flex; align-items: center; gap: 16px; font: 600 24px/1 var(--sans); }
.s-cover .brand svg, .s-fim .brand svg { width: 46px; height: 32px; }
.s-cover .display { margin-top: 104px; font: 600 220px/.86 var(--cond); letter-spacing: -.02em; }
.s-cover .lead { margin-top: 40px; font: 500 48px/1.15 var(--sans); }
.s-cover .sub { margin-top: 24px; font: 400 27px/1.42 var(--sans); color: #DDF0E7; }
.s-cover .team { position: absolute; left: 128px; right: 128px; bottom: 64px; display: grid; grid-template-columns: repeat(5, 1fr); column-gap: 32px; padding-top: 32px; border-top: 1px solid rgba(255, 255, 255, .3); }

/* --- 02 o problema ------------------------------------------------------- */
.s-problema .journey { position: relative; height: 296px; margin-top: 16px; }
.s-problema .layer { position: absolute; top: 0; height: 296px; }
.s-problema .layer svg { display: block; overflow: visible; }
.s-problema .ideal { fill: none; stroke: #B3AB98; stroke-width: 3; stroke-dasharray: 1 11; stroke-linecap: round; }
.s-problema .solid { fill: none; stroke: var(--green); stroke-width: 5; stroke-linecap: round; }
.s-problema .branch { fill: none; stroke: var(--red); stroke-width: 4; stroke-dasharray: 12 9; }
.s-problema .dead { stroke: var(--red); stroke-width: 4; stroke-linecap: round; }
.s-problema .bl { position: absolute; left: 380px; font: 600 28px/1 var(--sans); white-space: nowrap; transform: translateY(-50%); }
.s-problema .node { position: absolute; top: 132px; width: 36px; height: 36px; border-radius: 50%; }
.s-problema .node.ubs { left: 0; background: var(--green); }
.s-problema .node.esp { right: 0; background: var(--cream); box-shadow: inset 0 0 0 4px var(--ink); }
.s-problema .end { position: absolute; top: 196px; }
.s-problema .end b { display: block; font: 600 30px/1.1 var(--sans); }
.s-problema .end span { display: block; margin-top: 8px; font: 400 21px/1.3 var(--sans); color: var(--muted); }
.s-problema .end.esp { right: 0; text-align: right; }
.s-problema .lost { position: absolute; left: 1176px; width: 360px; top: 104px; text-align: center; font: 500 23px/1.2 var(--sans); color: var(--muted); }
.s-problema .who { margin-top: 88px; }
.s-problema .cell { padding-top: 24px; border-top: 2px solid var(--red); }
.s-problema .cell h3 { font: 600 32px/1.15 var(--sans); }
.s-problema .cell p { margin-top: 12px; font: 400 27px/1.4 var(--sans); color: var(--ink-2); }
.s-problema .c-cid { grid-column: 1 / span 3; }
.s-problema .c-ges { grid-column: 4 / span 3; }
.s-problema .c-tcu { grid-column: 7 / span 6; border-top-color: var(--ink); border-top-width: 1px; padding-top: 25px; }

/* --- 03 a espera custa saúde --------------------------------------------- */
.s-espera .stat-a { grid-column: 1 / span 5; }
.s-espera .stat-b { grid-column: 7 / span 6; }
.s-espera .big { display: block; font: 600 240px/.86 var(--cond); letter-spacing: -.02em; color: #fff; white-space: nowrap; }
.s-espera .big small { font-size: .5em; letter-spacing: 0; margin-left: 8px; }
.s-espera .stat { padding-top: 16px; }
.s-espera .stat p { margin-top: 32px; max-width: 680px; font: 400 32px/1.32 var(--sans); }
.s-espera .stat p strong { color: #fff; }
.s-espera .meter { position: relative; margin-top: 40px; height: 12px; border-radius: 6px; background: var(--red-900); }
.s-espera .meter i { position: absolute; left: 0; top: 0; bottom: 0; width: 94%; border-radius: 6px; background: var(--red); }
.s-espera .scale { display: flex; justify-content: space-between; margin-top: 12px; font: 400 19px/1 var(--sans); color: var(--night-muted); }
.s-espera .people { margin-top: 40px; display: flex; gap: 32px; align-items: flex-start; }
.s-espera .people figure { display: flex; flex-direction: column; align-items: center; gap: 12px; }
.s-espera .people svg { width: 64px; height: 96px; display: block; }
.s-espera .people .stay { fill: var(--night-muted); }
.s-espera .people .gone { fill: none; stroke: var(--red); stroke-width: 3; stroke-dasharray: 7 6; }
.s-espera .people figcaption { font: 500 19px/1 var(--sans); color: var(--night-muted); }
.s-espera .loses { position: absolute; left: 0; right: 0; bottom: 0; padding-top: 28px; border-top: 1px solid var(--night-rule); font: 400 32px/1.3 var(--sans); }

/* --- 04 o projeto -------------------------------------------------------- */
.s-projeto .app { grid-column: 1 / span 4; }
.s-projeto .screen { border-radius: 6px; overflow: hidden; border: 1px solid var(--rule); background: #F4F4F4; }
.s-projeto .screen img { display: block; width: 100%; }
.s-projeto .app figcaption { margin-top: 16px; }
.s-projeto .right { grid-column: 5 / span 8; display: flex; flex-direction: column; }
.s-projeto .what { max-width: 1040px; font: 500 36px/1.25 var(--sans); }
.s-projeto .channels { margin-top: 48px; display: grid; grid-template-columns: repeat(3, 1fr); column-gap: 32px; }
.s-projeto .ch { padding-top: 20px; border-top: 1px solid var(--ink); }
.s-projeto .ch h3 { margin-top: 8px; font: 600 28px/1.15 var(--sans); }
.s-projeto .ch ul { margin-top: 16px; display: flex; flex-direction: column; gap: 10px; font: 400 21px/1.35 var(--sans); color: var(--ink-2); }
.s-projeto .ch code { font: 500 18px/1 var(--mono); color: var(--green-700); margin-right: 8px; }
.s-projeto .callboard { margin-top: 16px; display: flex; gap: 40px; padding: 16px 20px; border-radius: 6px; background: var(--night); color: var(--night-text); }
.s-projeto .callboard span { display: block; font: 500 17px/1 var(--sans); color: var(--night-muted); }
.s-projeto .callboard b { display: block; margin-top: 8px; font: 600 44px/1 var(--mono); color: var(--yellow); }
.s-projeto .foot { margin-top: auto; }
.s-projeto .fase3 { display: grid; grid-template-columns: repeat(4, 1fr); column-gap: 32px; padding-top: 16px; border-top: 1px solid var(--rule); }
.s-projeto .fase3 .label { grid-column: 1 / -1; margin-bottom: 12px; }
.s-projeto .fase3 div { font: 400 21px/1.25 var(--sans); color: var(--ink-2); }
.s-projeto .fase3 div b { display: block; font: 600 56px/1 var(--cond); color: var(--green-700); }
.s-projeto .fase3 div.db b { color: var(--blue); }
.s-projeto .rnf { margin-top: 24px; padding-top: 16px; border-top: 1px solid var(--ink); font: 400 25px/1.35 var(--sans); }
.s-projeto .rnf code { font-weight: 600; font-size: 22px; margin-right: 16px; }

/* --- 05 onde a IA e os dados entram -------------------------------------- */
.s-onde .pipe { position: absolute; left: 0; right: 0; top: 88px; height: 600px; }
.s-onde .zone { position: absolute; top: 48px; height: 18px; border-top: 3px solid; }
.s-onde .zone::before, .s-onde .zone::after { content: ""; position: absolute; top: -3px; width: 3px; height: 18px; background: currentColor; }
.s-onde .zone::before { left: 0; }
.s-onde .zone::after { right: 0; }
.s-onde .zone span { position: absolute; left: 0; top: -44px; font: 600 24px/1 var(--sans); color: var(--ink); white-space: nowrap; }
.s-onde .z-ia { left: 0; width: 816px; color: var(--yellow-700); border-top-style: dashed; }
.s-onde .z-ds { left: 1272px; right: 0; color: var(--blue); }
.s-onde .loop { position: absolute; left: 0; top: 0; }
.s-onde .loop svg { display: block; }
.s-onde .loop path { fill: none; stroke: var(--red); stroke-width: 3; stroke-dasharray: 10 8; }
.s-onde .loop path.head { stroke-dasharray: none; stroke-linecap: round; stroke-linejoin: round; }
.s-onde .loop span { position: absolute; left: 186px; top: 142px; width: 80px; text-align: center; font: 600 22px/1 var(--sans); color: var(--red); }
.s-onde .rail { position: absolute; left: 14px; right: 0; top: 199px; height: 3px; background: var(--ink); }
.s-onde .stations { position: absolute; left: 0; right: 0; top: 186px; display: grid; grid-template-columns: repeat(4, 1fr); column-gap: 32px; }
.s-onde .stations li { position: relative; padding-top: 56px; }
.s-onde .stations .node { position: absolute; left: 0; top: 0; width: 28px; height: 28px; border-radius: 50%; background: var(--cream); box-shadow: inset 0 0 0 3px var(--ink); }
.s-onde .stations .ia .node { background: var(--yellow-200); box-shadow: none; border: 3px dashed var(--yellow-700); }
.s-onde .stations .ds .node { background: var(--blue); box-shadow: none; }
.s-onde .stations .n { font: 600 24px/1 var(--cond); color: var(--muted); }
.s-onde .stations h3 { margin-top: 8px; font: 600 34px/1.1 var(--sans); }
.s-onde .stations p { margin-top: 16px; font: 400 26px/1.38 var(--sans); color: var(--ink-2); }
.s-onde .stations p strong { color: var(--red); font-weight: 600; }
.s-onde .hyp { display: block; margin-top: 20px; padding-top: 12px; border-top: 1px dashed var(--faint); font: 400 20px/1.3 var(--sans); color: var(--muted); }

/* --- 06 o fluxo ---------------------------------------------------------- */
.s-fluxo .lede { font: 400 30px/1.3 var(--sans); color: var(--ink-2); }
.s-fluxo .lede b { color: var(--ink); }
.s-fluxo .flow { position: absolute; left: 0; right: 0; top: 96px; height: 480px; }
.s-fluxo .zone { position: absolute; top: 44px; height: 16px; border-top: 3px solid; }
.s-fluxo .zone::before, .s-fluxo .zone::after { content: ""; position: absolute; top: -3px; width: 3px; height: 16px; background: currentColor; }
.s-fluxo .zone::before { left: 0; }
.s-fluxo .zone::after { right: 0; }
.s-fluxo .zone span { position: absolute; left: 0; top: -40px; font: 600 22px/1 var(--sans); color: var(--ink); white-space: nowrap; }
.s-fluxo .z-ia { left: 281px; width: 820px; color: var(--yellow-700); border-top-style: dashed; }
.s-fluxo .z-hum { left: 1125px; width: 257px; color: var(--ink); }
.s-fluxo .z-mv { left: 1407px; width: 257px; color: var(--green); }
.s-fluxo .seg { position: absolute; top: 125px; height: 3px; width: 241px; background: var(--ink); }
.s-fluxo .seg.ok { background: var(--green); }
.s-fluxo .steps { position: absolute; left: 0; right: 0; top: 106px; display: grid; grid-template-columns: repeat(6, 1fr); column-gap: 24px; }
.s-fluxo .steps li { position: relative; padding-top: 64px; }
.s-fluxo .steps .node { position: absolute; left: 0; top: 0; width: 40px; height: 40px; border-radius: 50%; display: grid; place-items: center; font: 600 22px/1 var(--cond); background: var(--cream); box-shadow: inset 0 0 0 3px var(--ink); }
.s-fluxo .steps .ia .node { background: var(--yellow-200); box-shadow: none; border: 3px dashed var(--yellow-700); }
.s-fluxo .steps .hum .node { border-radius: 4px; transform: rotate(45deg) scale(.86); background: var(--ink); box-shadow: none; color: #fff; }
.s-fluxo .steps .hum .node span { transform: rotate(-45deg); }
.s-fluxo .steps .mv .node { background: var(--green); box-shadow: none; color: #fff; }
.s-fluxo .steps h3 { font: 600 30px/1.1 var(--sans); }
.s-fluxo .steps p { margin-top: 12px; font: 400 22px/1.36 var(--sans); color: var(--ink-2); }
.s-fluxo .steps code { display: block; margin-top: 16px; font: 500 17px/1.35 var(--mono); color: var(--muted); }
.s-fluxo .steps .ia code { color: var(--yellow-700); }
.s-fluxo .steps .mv code { color: var(--green-700); font-weight: 600; }
.s-fluxo .ring { position: absolute; left: 1115px; top: 96px; width: 60px; height: 60px; border-radius: 50%; box-shadow: 0 0 0 4px var(--yellow); }
.s-fluxo .limit { position: absolute; left: 0; right: 0; bottom: 0; padding-top: 24px; border-top: 1px solid var(--ink); font: 400 32px/1.3 var(--sans); }

/* --- 07 tela do médico (figura com câmera) ------------------------------- */
.s-tela .mock { position: absolute; inset: 0; background: #fff; color: var(--ink); }
.s-tela .bar { position: absolute; left: 0; right: 0; top: 0; height: 56px; display: flex; align-items: center; justify-content: space-between; padding: 0 24px; background: var(--cream-2); border-bottom: 1px solid var(--rule); font: 600 21px/1 var(--sans); }
.s-tela .bar span { font-weight: 400; color: var(--muted); }
.s-tela .bar small { font: 400 18px/1 var(--sans); color: var(--muted); }
.s-tela .frame { position: absolute; top: 72px; bottom: 16px; border-radius: 6px; }
.s-tela .frame.draft { border: 2px dashed var(--yellow-700); }
.s-tela .frame.ok { border: 2px solid var(--green); }
.s-tela .f-rel { left: 576px; width: 504px; }
.s-tela .f-ras { left: 1100px; right: 16px; }
.s-tela h4 { position: absolute; top: 88px; font: 600 22px/1 var(--sans); }
.s-tela h4 small { display: block; margin-top: 8px; font: 500 17px/1 var(--sans); color: var(--yellow-700); }
.s-tela h4 small.plain { color: var(--muted); font-weight: 400; }
.s-tela .h-tra { left: 24px; }
.s-tela .h-rel { left: 600px; }
.s-tela .h-ras { left: 1124px; }
.s-tela .row { position: absolute; display: flex; align-items: center; height: 72px; }
.s-tela .tra { left: 24px; width: 528px; gap: 16px; font: 400 20px/1.3 var(--sans); }
.s-tela .tra .who { flex: none; width: 92px; font: 500 17px/1 var(--sans); color: var(--muted); }
.s-tela .tra q { quotes: "“" "”"; }
.s-tela .tra .ex { background: var(--yellow-200); padding: 1px 4px; border-radius: 3px; }
.s-tela .tra .doc { color: var(--muted); }
.s-tela .k { font: 600 20px/1 var(--cond); color: var(--yellow-700); }
.s-tela .link { position: absolute; left: 536px; width: 80px; height: 0; border-top: 2px dashed var(--yellow-700); }
.s-tela .rel { left: 600px; width: 464px; flex-direction: column; align-items: flex-start; justify-content: center; }
.s-tela .rel span { font: 400 17px/1 var(--sans); color: var(--muted); }
.s-tela .rel b { margin-top: 6px; font: 600 21px/1.2 var(--sans); }
.s-tela .field { position: absolute; left: 1124px; right: 40px; }
.s-tela .field span { display: block; font: 400 17px/1 var(--sans); color: var(--muted); }
.s-tela .field b { display: block; margin-top: 6px; font: 600 22px/1.25 var(--sans); }
.s-tela .field p { margin-top: 6px; font: 400 19px/1.35 var(--sans); }
.s-tela .field code { display: block; margin-top: 6px; font: 500 15px/1.2 var(--mono); color: var(--green-700); }
.s-tela .field code.new { color: var(--muted); }
.s-tela .actions { position: absolute; left: 1124px; top: 468px; display: flex; gap: 12px; }
.s-tela .btn { padding: 12px 18px; border-radius: 6px; font: 600 19px/1 var(--sans); box-shadow: inset 0 0 0 1px var(--rule); background: #fff; }
.s-tela .btn.go { background: var(--green); color: #fff; box-shadow: none; }
.s-tela .btn.no { color: var(--red); }
.s-tela .hist { position: absolute; left: 1124px; right: 40px; top: 532px; padding-top: 14px; border-top: 1px solid var(--rule); font: 400 15px/1.55 var(--mono); color: var(--ink-2); }
.s-tela .hist b { color: var(--green-700); }

/* --- 08 painel do gestor ------------------------------------------------- */
.s-painel .strip { display: flex; align-items: center; gap: 20px; font: 500 22px/1 var(--sans); color: var(--ink-2); }
.s-painel .strip i { font-style: normal; color: var(--faint); }
.s-painel .strip b { color: var(--blue); }
.s-painel .panel { position: absolute; left: 0; right: 0; top: 64px; bottom: 48px; border-radius: 6px; background: #fff; box-shadow: inset 0 0 0 1px var(--rule); }
.s-painel .phead { position: absolute; left: 32px; right: 32px; top: 28px; display: flex; justify-content: space-between; align-items: baseline; padding-bottom: 20px; border-bottom: 1px solid var(--rule); font: 600 22px/1 var(--sans); }
.s-painel .phead span { font: 400 19px/1 var(--sans); color: var(--muted); }
.s-painel .chart-block { position: absolute; left: 32px; top: 100px; width: 1040px; }
.s-painel .heat-block { position: absolute; right: 32px; top: 100px; width: 464px; }
.s-painel h4 { font: 600 24px/1.2 var(--sans); }
.s-painel h4 + .label { margin-top: 6px; }
.s-painel .chart { display: block; margin-top: 8px; overflow: visible; }
.s-painel .chart .grid { stroke: #ECE7DB; stroke-width: 1; }
.s-painel .chart .grid.base { stroke: var(--rule); }
.s-painel .chart .ytick { font: 400 18px var(--sans); fill: var(--muted); text-anchor: end; dominant-baseline: middle; }
.s-painel .chart .xtick { font: 400 18px var(--sans); fill: var(--muted); text-anchor: middle; }
.s-painel .chart .today { stroke: var(--ink); stroke-width: 1.5; stroke-dasharray: 4 6; }
.s-painel .chart .today-t { font: 500 18px var(--sans); fill: var(--ink); }
.s-painel .chart .today-t.end { text-anchor: end; }
.s-painel .chart .today-t.fc { fill: var(--muted); }
.s-painel .chart .band { fill: var(--blue-100); }
.s-painel .chart .ln { fill: none; stroke-width: 2.5; stroke-linejoin: round; stroke-linecap: round; }
.s-painel .chart .ln.ctx { stroke: #8A948E; }
.s-painel .chart .ln.hot { stroke: var(--blue); stroke-width: 4; }
.s-painel .chart .ln.fc { stroke-dasharray: 1 9; }
.s-painel .chart .ln.fc.hot { stroke-dasharray: 2 9; }
.s-painel .chart .dl { font: 500 19px var(--sans); fill: var(--ink-2); dominant-baseline: middle; }
.s-painel .chart .dl.hot { font-weight: 600; fill: var(--ink); }
.s-painel .chart .dl .v { fill: var(--muted); font-weight: 400; }
.s-painel .chart .annot { font: 600 20px var(--sans); fill: var(--ink); text-anchor: end; }
.s-painel .chart .dot { fill: var(--blue); stroke: #fff; stroke-width: 2; }
.s-painel .hm { margin-top: 20px; display: grid; grid-template-columns: 72px 1fr 1fr; gap: 4px; }
.s-painel .hm .h { font: 500 18px/1 var(--sans); color: var(--muted); padding-bottom: 6px; }
.s-painel .hm .d { display: flex; align-items: center; font: 500 20px/1 var(--sans); color: var(--ink-2); }
.s-painel .hm .c { height: 60px; display: flex; align-items: center; padding-left: 16px; border-radius: 4px; font: 600 22px/1 var(--sans); font-variant-numeric: tabular-nums; color: var(--ink); }
.s-painel .hm .b1 { background: var(--blue-100); }
.s-painel .hm .b2 { background: var(--blue-200); }
.s-painel .hm .b3 { background: var(--blue-300); }
.s-painel .hm .b4 { background: var(--blue-400); color: #fff; }
.s-painel .hm .b5 { background: var(--blue); color: #fff; }
.s-painel .h-annot { margin-top: 16px; font: 400 21px/1.35 var(--sans); color: var(--ink-2); }
.s-painel .h-annot b { color: var(--ink); }

/* --- 09 benefícios e desafios -------------------------------------------- */
.s-balanco .col-b { grid-column: 1 / span 5; }
.s-balanco .col-d { grid-column: 6 / span 7; }
.s-balanco .head { padding-bottom: 16px; border-bottom: 2px solid var(--green); }
.s-balanco .col-d .head { border-bottom-color: var(--red); }
.s-balanco .head h3 { font: 600 30px/1.1 var(--sans); }
.s-balanco .head p { margin-top: 8px; font: 400 23px/1.3 var(--sans); color: var(--ink-2); }
.s-balanco .rows li { position: relative; display: grid; grid-template-columns: 168px 1fr; column-gap: 24px; padding: 13px 0; border-bottom: 1px solid var(--rule); font: 400 21px/1.35 var(--sans); color: var(--ink-2); }
.s-balanco .col-d .rows li { grid-template-columns: 288px 1fr; }
.s-balanco .rows b { position: relative; font: 600 22px/1.3 var(--sans); color: var(--ink); }
.s-balanco .rows span { position: relative; }
.s-balanco .rows .hl { position: absolute; top: 0; bottom: 0; left: -12px; right: -12px; border-radius: 4px; background: rgba(245, 183, 0, .2); }

/* --- 10 a IA não decide (encerramento) ----------------------------------- */
.s-fim .no { margin-top: 80px; max-width: 1560px; font: 600 96px/1 var(--cond); letter-spacing: -.01em; }
.s-fim .rules { margin-top: 56px; display: grid; grid-template-columns: repeat(5, 1fr); column-gap: 32px; padding-top: 24px; border-top: 1px solid rgba(255, 255, 255, .3); }
.s-fim .rules .n { font: 600 44px/1 var(--cond); color: var(--yellow); }
.s-fim .rules p { margin-top: 12px; font: 400 24px/1.32 var(--sans); }
.s-fim .rules code { font-size: 22px; }
.s-fim .end { position: absolute; left: 128px; right: 128px; bottom: 64px; display: grid; grid-template-columns: repeat(12, 1fr); column-gap: 32px; align-items: end; }
.s-fim .decide { grid-column: 1 / span 7; }
.s-fim .decide p { font: 500 48px/1.2 var(--sans); }
.s-fim .decide .links { margin-top: 32px; font: 500 22px/1.6 var(--mono); color: #DDF0E7; }
.s-fim .decide .links .video-link { color: #fff; }
.s-fim .thanks { grid-column: 8 / span 5; text-align: right; font: 600 140px/.86 var(--cond); letter-spacing: -.02em; }
